import "./TopSeries.css";

const TopSeries = ({Series, topTenSeries, setSelectedDiv, handleSelectChange, setOptionValue}) => {

  return (
    <div className="top-series">
      {topTenSeries.map((item, idx) => (
        <div
          key={idx}
		  onClick={() => {const shortCut = Series.find(row => row["value"] === item["Series"]); setOptionValue(shortCut); setSelectedDiv(shortCut); handleSelectChange(shortCut);}}
          className={`rank rank-${idx + 1}`}
          style={{

            width:
              idx === 0
                ? "100%"
                : idx === 1
                ? "85%"
                : idx === 2 
                ? "80%"
				: idx === 7
                ? "60%"
                : idx === 8
                ? "50%"
                : idx === 9
                ? "50%"
                : "70%",
          }}
        >
          {idx + 1}. {item["Series"]} ({item["Total Points"]})
        </div>
      ))}
    </div>
  );
};

export default TopSeries;
