import React from 'react';
import { StyleSheet } from 'react-native';

const InfoFooter = ({lastModified}) => {
	
	const styles = StyleSheet.create({
		lastModifiedText: {
			fontSize: "12px",
		},

	});
  
  return (
   <footer>
    <p> I only meant to stay a while... </p>
    <p> Made by CoolTaff12 </p>
	<p style={styles.lastModifiedText}>{lastModified !== null ? "Last updated: " + lastModified : ""}</p>
   </footer>
  );

}

export default InfoFooter; 