const CustomizedContent = (props) => {
  const { x, y, width, height, name, value, img } = props;
  return (
    <g>
      <rect
        x={x}
        y={y}
        width={width}
        height={height}
        style={{ fill: "none", stroke: "#fff" }}
      />
      <image
        href={img}
        x={x + 5}
        y={y + 5}
        width={width - 10}
        height={height - 30}
        preserveAspectRatio="xMidYMid slice"
      />
      <text
        x={x + width / 2}
        y={y + height - 10}
        textAnchor="middle"
        fontSize={value > 60 ? 14 : 11}
        fill="#333"
      >
        {name}
      </text>
    </g>
  );
};

export default function BildTreemap() {
  return (
    <ResponsiveContainer width={1157} height={900}>
      <Treemap
        data={data}
        dataKey="value"
        stroke="#fff"
        content={<CustomizedContent />}
      />
    </ResponsiveContainer>
  );
}
